                <>
                  <ActionButton 
                    variant="stop" 
                    onClick={() => handleStopServer(server.id)}
                  >
                    Stop
                  </ActionButton>
                  <ActionButton 
                    variant="restart" 
                    onClick={() => handleRestartServer(server.id)}
                  >
                    Restart
                  </ActionButton>
                </>
              )}
            </ServerActions>
          </ServerCard>
        ))}
      </ServerCardsGrid>
    </ServerCardSection>
  );
};

